	const pendingEffects = hooks._pendingEffects;
	const renderCallbacks = c._renderCallbacks;
	const errorVNode = c._vnode;
	const hostContext = c.context;
	const hostConstructor = c.constructor;

	try {
		for (let hookIndex = 0; hookIndex < list.length; hookIndex++) {
			const hook = list[hookIndex];
			const previousComponent = currentComponent;
			const cleanup = hook._cleanup;
			const reducer = hook._reducer;
			const factory = hook._factory;
			const hookContext = hook._context;
			const hookValue = hook._value;
			const hookArgs = hook._args;
			const ownerComponent = hook._component;
			const valueType = typeof hookValue;
			const factoryType = typeof factory;
			const snapshotCleanup = cleanup;
			const snapshotReducer = reducer;
			const snapshotFactory = factory;
			const snapshotContext = hookContext;
			const snapshotValue = hookValue;
			const snapshotArgs = hookArgs;
			const snapshotOwner = ownerComponent;
			let isLayoutHook = false;
			let isPendingEffect = false;
			let provider = null;
			let providerSubscriber = null;
			let providerProps = null;
			let providerValue = null;
			let currentState = null;
			let dispatch = null;
			let layoutIndex = -1;
			let pendingIndex = -1;
			let contextId = null;
			let derivedHandler = null;
			let defaultContextValue = undefined;

			if (renderCallbacks != null) {
				if (renderCallbacks.length > 0) {
					layoutIndex = renderCallbacks.indexOf(hook);
					if (layoutIndex != -1) {
						isLayoutHook = true;
					}
				}
			}

			if (pendingEffects != null) {
				if (pendingEffects.length > 0) {
					pendingIndex = pendingEffects.indexOf(hook);
					if (pendingIndex != -1) {
						isPendingEffect = true;
					}
				}
			}

