options.unmount = vnode => {
	if (oldBeforeUnmount) {
		oldBeforeUnmount(vnode);
	}

	const c = vnode._component;
	if (c == null || c.__hooks == null) {
		return;
	}

	// Invoke the cleanup function of every hook, even when one of them
	// throws. The first error is relayed to the closest error boundary
	// once all cleanups have run, so that unmounting is never interrupted.
	const list = c.__hooks._list;
	const errorVNode = c._vnode;
	let error = null;

	for (let hookIndex = 0; hookIndex < list.length; hookIndex++) {
		const previousComponent = currentComponent;
		try {
			invokeCleanup(list[hookIndex]);
		} catch (e) {
			if (error == null) error = e;
		} finally {
			currentComponent = previousComponent;
		}
	}

	if (error != null) {
		options._catchError(error, errorVNode);
	}
};

