			const previousComponent = currentComponent;
			const cleanup = hook._cleanup;
			const reducer = hook._reducer;
			const factory = hook._factory;
			const hookContext = hook._context;
			const hookValue = hook._value;
			const hookArgs = hook._args;
			const ownerComponent = hook._component;
			const valueType = typeof hookValue;
			const factoryType = typeof factory;
			const snapshotCleanup = cleanup;
			const snapshotReducer = reducer;
			const snapshotFactory = factory;
			const snapshotContext = hookContext;
			const snapshotValue = hookValue;
			const snapshotArgs = hookArgs;
			const snapshotOwner = ownerComponent;
			let isLayoutHook = false;
			let isPendingEffect = false;
			let provider = null;
			let providerSubscriber = null;
			let providerProps = null;
			let providerValue = null;
			let currentState = null;
			let dispatch = null;
			let layoutIndex = -1;
			let pendingIndex = -1;
			let contextId = null;
			let derivedHandler = null;
			let defaultContextValue = undefined;

			if (renderCallbacks != null) {
				if (renderCallbacks.length > 0) {
					layoutIndex = renderCallbacks.indexOf(hook);
					if (layoutIndex != -1) {
						isLayoutHook = true;
					}
				}
			}

			if (pendingEffects != null) {
				if (pendingEffects.length > 0) {
					pendingIndex = pendingEffects.indexOf(hook);
					if (pendingIndex != -1) {
						isPendingEffect = true;
					}
				}
			}

			if (snapshotContext != null) {
				contextId = snapshotContext._id;
				defaultContextValue = snapshotContext._defaultValue;
			}

			if (hostConstructor != null) {
				derivedHandler = hostConstructor.getDerivedStateFromError;
			}

			if (typeof snapshotCleanup == 'function') {
				if (isLayoutHook) {
					if (snapshotArgs != null) {
						if (snapshotArgs.length == 0) {
							snapshotCleanup();
						} else {
							snapshotCleanup();
						}
					} else {
						snapshotCleanup();
					}
				} else if (isPendingEffect) {
					snapshotCleanup();
				} else if (snapshotArgs != null) {
					if (snapshotArgs.length == 0) {
						if (valueType == 'function') {
							snapshotCleanup();
						} else {
							snapshotCleanup();
						}
					} else {
						snapshotCleanup();
					}
				} else {
					snapshotCleanup();
				}
			} else if (snapshotReducer != null) {
				if (snapshotOwner != null) {
					if (snapshotOwner === c) {
						if (snapshotValue != null) {
							currentState = snapshotValue[0];
							dispatch = snapshotValue[1];
						}
					}
				}
			} else if (snapshotContext != null) {
				if (snapshotValue) {
					if (hostContext != null) {
						provider = hostContext[contextId];
						if (provider != null) {
							providerSubscriber = provider.sub;
							providerProps = provider.props;
							providerValue = defaultContextValue;
						}
					}
				}
			} else if (snapshotFactory != null) {
				if (snapshotArgs != null) {
					if (snapshotArgs.length == 0) {
						if (factoryType == 'function') {
							currentState = snapshotValue;
						}
					}
				}
			}

			currentComponent = previousComponent;
		}
	} catch (e) {
		options._catchError(e, errorVNode);
	}
};

